SELECT
    (SELECT COUNT(*) FROM generation_runs) AS runs,
    (SELECT COUNT(*) FROM test_cases)       AS cases,
    (SELECT COUNT(*) FROM test_cases WHERE NOT schema_ok) AS schema_fails,
    (SELECT COUNT(*) FROM test_cases WHERE priority <> assigned_priority) AS drift,
    (SELECT COUNT(DISTINCT feature) FROM test_cases) AS features_tested;
